import 'dart:collection';

import 'package:flutter/foundation.dart';

import 'sfra_protocol.dart';

/// Origin of a [CommunicationLogEntry].
enum LogDirection {
  /// Text written by the app to the microcontroller.
  sent,

  /// Text notified by the microcontroller to the app.
  received,

  /// Connection events and other notes generated by the app.
  info,

  /// Failures (send errors, connection errors, timeouts...).
  error,
}

@immutable
class CommunicationLogEntry {
  const CommunicationLogEntry({
    required this.time,
    required this.direction,
    required this.text,
    this.response,
  });

  final DateTime time;
  final LogDirection direction;
  final String text;

  /// Classification of [text] for [LogDirection.received] entries.
  final DeviceResponse? response;

  @override
  String toString() => '[${direction.name}] $text';
}

/// Bounded, observable history of everything exchanged with the robot.
///
/// Displayed by the command window of the manual control page.
class CommunicationLog extends ChangeNotifier {
  CommunicationLog({this.capacity = 500, DateTime Function()? clock})
    : _clock = clock ?? DateTime.now;

  /// Oldest entries are dropped once this many are stored.
  final int capacity;
  final DateTime Function() _clock;
  final List<CommunicationLogEntry> _entries = [];

  /// Entries in chronological order (oldest first).
  List<CommunicationLogEntry> get entries => UnmodifiableListView(_entries);

  bool get isEmpty => _entries.isEmpty;

  void sent(String text) => _add(LogDirection.sent, text);

  void received(String text) => _add(
    LogDirection.received,
    text,
    response: SfraProtocol.parseResponse(text),
  );

  void info(String text) => _add(LogDirection.info, text);

  void error(String text) => _add(LogDirection.error, text);

  void clear() {
    if (_entries.isEmpty) return;
    _entries.clear();
    notifyListeners();
  }

  void _add(LogDirection direction, String text, {DeviceResponse? response}) {
    _entries.add(
      CommunicationLogEntry(
        time: _clock(),
        direction: direction,
        text: text,
        response: response,
      ),
    );
    if (_entries.length > capacity) {
      _entries.removeRange(0, _entries.length - capacity);
    }
    notifyListeners();
  }
}
